    SELECT fn_get_dynamic_seq('utb_app_locarno')


INSERT INTO utb_app_locarno (
    office_seq
    , app_seq
    , locarno_seq
    , class_no
    , sub_class_no
    , goods_seq
    , locarno_group_id
    , locarno_name_ko
    , locarno_name_en
    , goods_count
    , create_user
    , create_at
    , del_yn
) VALUES (
    #{officeSeq}
    , #{appSeq}
    , #{locarnoSeq}
    , #{classNo}
    , #{subClassNo}
    , #{goodsSeq}
    , #{locarnoGroupId}
    , #{locarnoNameKo}
    , #{locarnoNameEn}
    , #{goodsCount}
    , #{createUser}
    , CURRENT_TIMESTAMP
    , #{delYn}
)

mapper.select:
SELECT class_no , locarno_version , category_gb , class_nm_ko , class_nm_en , class_desc_ko , class_desc_en , del_yn , create_user , create_at , update_user , update_at FROM utb_locarno_mst WHERE 1=1 AND del_yn = 'N'
AND locarno_version = #{locarnoVersion}
ORDER BY class_no ASC, locarno_version DESC

SELECT class_no , subclass_no , locarno_version , subclass_nm_ko , subclass_nm_en , del_yn , create_user , create_at , update_user , update_at FROM utb_locarno_subclass_mst WHERE 1=1 AND del_yn = 'N' AND class_no = #{classNo}
AND locarno_version = #{locarnoVersion}
ORDER BY subclass_no ASC, locarno_version DESC

SELECT G.goods_seq , G.class_no , G.subclass_no , G.locarno_version , G.goods_no , G.goods_nm_ko , G.goods_nm_en /* 필요 시 마스터 명칭 조인 필드 추가 */ , S.subclass_nm_ko , G.del_yn , G.create_user AS createUser , G.create_at AS createAt FROM utb_locarno_goods_mst G LEFT JOIN utb_locarno_subclass_mst S ON G.class_no = S.class_no AND G.subclass_no = S.subclass_no AND G.locarno_version = S.locarno_version WHERE G.del_yn = 'N' AND G.class_no = #{classNo} AND G.subclass_no = #{subclassNo}
AND G.locarno_version = #{locarnoVersion}
ORDER BY G.goods_no ASC, G.goods_seq DESC

SELECT
    COUNT(*)
FROM utb_app_locarno
WHERE locarno_group_id = #{locarnoGroupId}
  AND app_seq = #{appSeq}
  AND office_seq = #{officeSeq}
  AND del_yn = 'N'

